ining creates one graphite unit in the miner's represented stock.","actor_selector":{"categories":["miner"],"components":["business"]},"participants":{},"parameters":{},"checks":[{"label":"the miner has a waiting work order","left":{"participant":{"name":"actor","path":"components.business.work_waiting"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.business.graphite","op":"add","value":{"literal":1}}],"limits":["The world represents no graphite reserve, so reserve depletion and renewal are omitted."],"tests":["The miner gains one graphite unit."] ,"semantic_bindings":["graphite means mined graphite"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"supply-clay-to-lead-works","version":"1","action_kind":"supply-clay","rationale":"Supplying clay transfers one unit from the supplier's represented stock to the lead works.","actor_selector":{"categories":["supplier"],"components":["business"]},"participants":{"lead_works":{"categories":["processor"],"components":["business"]}},"parameters":{},"checks":[{"label":"the supplier and lead works are in the same place","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"lead_works","path":"location.location_id"}}},{"label":"the supplier has clay to supply","left":{"participant":{"name":"actor","path":"components.business.clay"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.business.clay","op":"subtract","value":{"literal":1}},{"participant":"lead_works","path":"components.business.clay","op":"add","value":{"literal":1}}],"limits":["Supply is refused unless the supplier already holds clay; no clay source stock is represented."],"tests":["With clay in stock and both parties at one place, one unit moves to the lead works."] ,"semantic_bindings":["clay moves from supplier to lead works"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"mix-graphi