ay-leads","version":"1","action_kind":"mix-leads","rationale":"Mixing consumes one graphite and one clay and creates one lead in the processor's stocks.","actor_selector":{"categories":["processor"],"components":["business"]},"participants":{},"parameters":{},"checks":[{"label":"the lead works has graphite","left":{"participant":{"name":"actor","path":"components.business.graphite"}},"op":"gt","right":{"literal":0}},{"label":"the lead works has clay","left":{"participant":{"name":"actor","path":"components.business.clay"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.business.graphite","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.clay","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.leads","op":"add","value":{"literal":1}}],"limits":["One unit of each input produces one lead; different recipes and yields are not represented."],"tests":["With one graphite and one clay, mixing consumes both and adds one lead."] ,"semantic_bindings":["graphite and clay consumed","leads produced"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"assemble-pencil","version":"1","action_kind":"make-pencils","rationale":"Pencil assembly consumes one lead, slat, and each represented finishing supply, producing one pencil.","actor_selector":{"categories":["factory"],"components":["business"]},"participants":{},"parameters":{},"checks":[{"label":"the factory has a lead","left":{"participant":{"name":"actor","path":"components.business.leads"}},"op":"gt","right":{"literal":0}},{"label":"the factory has a cedar slat","left":{"participant":{"name":"actor","path":"components.business.cedar_slats"}},"op":"gt","right":{"literal":0}},{"label":"the factory has paint","left":{"participant":{"name":"actor","path":"components.business.paint"}},"op":"gt","right":{"literal":0}},{"label":"the factory has an eraser","left":{"participant":{"name":"actor","path":"components.business.erasers"}},"op":"gt","right":{"literal":0}},{"label":"the factory has a brass ferrule","left":{"participant":{"name":"actor","path":"components.business.brass_ferrules"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.business.leads","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.cedar_slats","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.paint","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.erasers","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.brass_ferrules","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.pencils","op":"add","value":{"literal":1}}],"limits":["The action requires the named finishing supplies; no source or delivery of those supplies is represented."],"tests":["With all five inputs present, one pencil is assembled and each input falls by one."] ,"semantic_bindings":["leads and cedar_slats consumed","paint, erasers, and brass_ferrules consumed","pencils produced"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"pack-pencil","version":"1","action_kind":"pack-pencils","rationale":"Packing transfers one finished pencil from loose to packed stock and consumes one box.","actor_selector":{"categories":["factory"],"components":["business"]},"participants":{},"parameters":{},"checks":[{"label":"the factory has a pencil","left":{"participant":{"name":"actor","path":"components.business.pencils"}},"op":"gt","right":{"literal":0}},{"label":"the factory has a box","left":{"participant":{"name":"actor","path":"components.business.boxes"}},"op":"gt","right":{"literal":0}}],"effects":[{"participant":"actor","path":"components.business.pencils","op":"subtract","value":{"literal":1}},{"participant":"actor","path":"components.business.packed_pencils","op":"add","value":{"literal":1}},{"participant":"actor","path":"components.business.boxes","op":"subtract","value":{"literal":1}}],"limits":["The represented stock counts packed pencils as individual pencils; box capacity is not represented."],"tests":["With a pencil and box available, packing transfers one pencil to packed stock and consumes one box."] ,"semantic_bindings":["pencils packed","boxes consumed"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"dispatch-packed-pencils","version":"1","action_kind":"dispatch-boxes","rationale":"Dispatch transfers the requested positive quantity from the carrier's packed stock into the referenced shipment and starts its represented journey countdown.","actor_selector":{"categories":["carrier"],"components":["business"]},"participants":{"to":{"categories":["shop"],"components":["business"]}},"parameters":{"quantity":[1,1000000]},"checks":[{"label":"the shipment quantity is positive","left":{"action_field":"quantity"},"op":"gt","right":{"literal":0}},{"label":"the trucker has enough packed pencils","left":{"participant":{"name":"actor","path":"components.business.packed_pencils"}},"op":"gte","right":{"action_field":"quantity"}},{"label":"the delivery is not already in transit","left":{"entity_id":"delivery"},"op":"eq","right":{"literal":"delivery"}}],"effects":[{"participant":"actor","path":"components.business.packed_pencils","op":"subtract","value":{"action_field":"quantity"}},{"participant":"to","path":"components.business.packed_pencils","op":"add","value":{"action_field":"quantity"}}],"limits":["Shipment entity state is not an action participant or writable target under this contract, so travel countdown and arrival are omitted; dispatch only transfers packed stock to the referenced shop.","This conservative mechanic does not model boxes as a separate shipment quantity."],"tests":["A positive quantity no greater than the carrier's packed stock can be dispatched.","A zero or excessive quantity is refused."] ,"semantic_bi